import pool from '../../db';
import {
  generatePassword,
  hashPassword,
  isValidUsername,
  normalizeUsername,
} from '../passwords';
import { toStaffAccount } from '../staffAuth';

// OAP staff accounts (staff_accounts table), managed from the staff portal's
// Users tab. Passwords are generated by the system and shown once.

export class StaffAdminError extends Error {
  constructor(message, status) {
    super(message);
    this.status = status;
  }
}

async function logHistory(conn, actor, entityType, entityId, action, notes = null) {
  await conn.query(
    `INSERT INTO edit_history (staff_id, entity_type, entity_id, action, notes)
     VALUES (?, ?, ?, ?, ?)`,
    [actor, entityType, String(entityId), action, notes]
  );
}

export async function listStaffAccounts() {
  const [rows] = await pool.query(
    `SELECT staff_account_id, username, is_active, created_at, created_by
     FROM staff_accounts ORDER BY is_active DESC, username`
  );
  return rows.map(toStaffAccount);
}

/** Creates an account. Returns { account, password }; the password is only shown once. */
export async function createStaffAccount(rawUsername, actor) {
  const username = normalizeUsername(rawUsername);
  if (!isValidUsername(username)) {
    throw new StaffAdminError(
      'Username must be 3-30 characters: lowercase letters, numbers, "_" or "-".',
      400
    );
  }

  const password = generatePassword();
  const conn = await pool.getConnection();
  try {
    await conn.beginTransaction();
    const [result] = await conn.query(
      `INSERT INTO staff_accounts (username, password_hash, created_by) VALUES (?, ?, ?)`,
      [username, hashPassword(password), actor.username]
    );
    await logHistory(conn, actor.username, 'staff_account', username, 'Staff account created');
    await conn.commit();
    return {
      account: toStaffAccount({
        staff_account_id: result.insertId,
        username,
        is_active: 1,
        created_at: new Date(),
        created_by: actor.username,
      }),
      password,
    };
  } catch (error) {
    await conn.rollback();
    if (error.code === 'ER_DUP_ENTRY') {
      throw new StaffAdminError(`The username "${username}" is already taken.`, 409);
    }
    throw error;
  } finally {
    conn.release();
  }
}

async function lockAccount(conn, id) {
  const [[row]] = await conn.query(
    `SELECT staff_account_id, username, is_active, created_at, created_by
     FROM staff_accounts WHERE staff_account_id = ? FOR UPDATE`,
    [id]
  );
  if (!row) throw new StaffAdminError('Staff account not found.', 404);
  return row;
}

/** Deactivate (blocks login immediately) or reactivate an account. */
export async function setStaffAccountActive(id, isActive, actor) {
  const conn = await pool.getConnection();
  try {
    await conn.beginTransaction();
    const row = await lockAccount(conn, id);

    if (!isActive) {
      if (row.username === actor.username) {
        throw new StaffAdminError("You can't deactivate your own account.", 400);
      }
      const [[{ activeCount }]] = await conn.query(
        `SELECT COUNT(*) AS activeCount FROM staff_accounts WHERE is_active = TRUE FOR UPDATE`
      );
      if (row.is_active && activeCount <= 1) {
        throw new StaffAdminError('At least one staff account must stay active.', 400);
      }
    }

    if (Boolean(row.is_active) !== isActive) {
      await conn.query(`UPDATE staff_accounts SET is_active = ? WHERE staff_account_id = ?`, [isActive, id]);
      await logHistory(
        conn,
        actor.username,
        'staff_account',
        row.username,
        isActive ? 'Staff account reactivated' : 'Staff account deactivated'
      );
    }
    await conn.commit();
    return toStaffAccount({ ...row, is_active: isActive });
  } catch (error) {
    await conn.rollback();
    throw error;
  } finally {
    conn.release();
  }
}

/** Generates a new password for someone else's account. Returns { account, password }. */
export async function resetStaffPassword(id, actor) {
  const password = generatePassword();
  const conn = await pool.getConnection();
  try {
    await conn.beginTransaction();
    const row = await lockAccount(conn, id);
    if (row.username === actor.username) {
      throw new StaffAdminError(
        'Ask another staff member to reset your password (or use `npm run create-staff -- <username> --reset`).',
        400
      );
    }
    await conn.query(`UPDATE staff_accounts SET password_hash = ? WHERE staff_account_id = ?`, [
      hashPassword(password),
      id,
    ]);
    await logHistory(conn, actor.username, 'staff_account', row.username, 'Password reset');
    await conn.commit();
    return { account: toStaffAccount(row), password };
  } catch (error) {
    await conn.rollback();
    throw error;
  } finally {
    conn.release();
  }
}

// ── Renters (users table) ────────────────────────────────────────────────────

export async function listRenters() {
  const [rows] = await pool.query(
    `SELECT bnumber, name, email, role, is_active FROM users ORDER BY is_active DESC, name`
  );
  return rows.map(r => ({
    bNumber: r.bnumber,
    fullName: r.name,
    email: r.email,
    userType: r.role,
    isActive: Boolean(r.is_active),
  }));
}

/** Deactivate (blocks reserving) or reactivate a renter. History is kept. */
export async function setRenterActive(bNumber, isActive, actor) {
  const conn = await pool.getConnection();
  try {
    await conn.beginTransaction();
    const [[row]] = await conn.query(
      `SELECT bnumber, name, email, role, is_active FROM users WHERE bnumber = ? FOR UPDATE`,
      [bNumber]
    );
    if (!row) throw new StaffAdminError('User not found.', 404);
    if (Boolean(row.is_active) !== isActive) {
      await conn.query(`UPDATE users SET is_active = ? WHERE bnumber = ?`, [isActive, bNumber]);
      await logHistory(conn, actor.username, 'user', bNumber, isActive ? 'User reactivated' : 'User deactivated');
    }
    await conn.commit();
    return {
      bNumber: row.bnumber,
      fullName: row.name,
      email: row.email,
      userType: row.role,
      isActive,
    };
  } catch (error) {
    await conn.rollback();
    throw error;
  } finally {
    conn.release();
  }
}
